def gen(rng):
    def fmt(g):
        return f"{len(g)} {len(g[0])}\n" + '\n'.join(' '.join(map(str, row)) for row in g)

    def tri(x, hi):
        p = 2 * hi
        x %= p
        return x if x <= hi else p - x

    tests = [fmt([[5]]), fmt([[1, 2, 3]]), fmt([[1], [2], [3]]), fmt([[1, 3], [2, 4]]),
             fmt([[0, 1], [1, 0]]), fmt([[2, 2], [2, 2]]), fmt([[3, 4, 5], [4, 9, 6], [5, 6, 7]]),
             fmt([[1, 2, 1, 2], [2, 1, 2, 1], [1, 2, 1, 2]])]
    for _ in range(45):
        r = rng.randint(1, 7)
        c = rng.randint(1, 7)
        hi = rng.choice([1, 2, 3])
        tests.append(fmt([[rng.randint(0, hi) for _ in range(c)] for _ in range(r)]))
    for _ in range(10):
        r = rng.randint(2, 8)
        c = rng.randint(2, 8)
        g = [[0] * c for _ in range(r)]
        for i in range(r):
            for j in range(c):
                if i == 0 and j == 0:
                    g[i][j] = 4
                elif rng.random() < 0.8:
                    if i > 0 and (j == 0 or rng.random() < 0.5):
                        base = g[i - 1][j]
                    else:
                        base = g[i][j - 1]
                    g[i][j] = max(0, base + rng.choice([-1, 1]))
                else:
                    g[i][j] = rng.randint(0, 8)
        tests.append(fmt(g))
    R = C = 600
    tests.append(fmt([[(i + j) % 2 for j in range(C)] for i in range(R)]))
    tests.append(fmt([[tri(i + j, 49) for j in range(C)] for i in range(R)]))
    g = [[0] * C for _ in range(R)]
    for i in range(R):
        for j in range(C):
            if i == 0 and j == 0:
                g[i][j] = 50
            elif rng.random() < 0.9:
                if i > 0 and (j == 0 or rng.random() < 0.5):
                    base = g[i - 1][j]
                else:
                    base = g[i][j - 1]
                g[i][j] = min(99, max(0, base + rng.choice([-1, 1])))
            else:
                g[i][j] = rng.randint(0, 99)
    tests.append(fmt(g))
    tests.append(fmt([[rng.randint(0, 2) for _ in range(C)] for _ in range(R)]))
    tests.append(fmt([[tri(j, 49) for j in range(600)]]))
    return tests
